FD='src.book.reis-housley-fundamentals-data-engineering'; DD='src.book.kleppmann-ddia.1e'; AR='src.web.aws-timeouts-retries-backoff'; AS='src.web.airbyte-schema-change-management'; DI='src.web.dbt-incremental-models'; PT='src.web.postgresql-transactions'; IR='src.web.apache-iceberg-reliability'; SI='src.web.stripe-idempotent-requests'; GP='src.web.google-sre-postmortem-culture'
