LESSONS=(
Lesson(246,'Lesson_246-game-day-provider-throttling-cursor-expiry-and-duplicate-delivery','Game Day Provider Throttling Cursor Expiry and Duplicate Delivery','134-game-day-provider-throttling-cursor-expiry-duplicate-delivery.md','wiki.ingestion.game-day-throttling-cursor-expiry-duplicates','Một game day ingestion chứng minh khả năng phát hiện, cô lập và phục hồi ba lỗi nhà cung cấp mà không gây mất hoặc nhân dữ liệu thế nào?',(AR,AS,FD,GP),(ARL,ASL,FDL,GPL),(
('Game day không phải demo','Chốt hypothesis, steady-state baseline, blast radius, synthetic source/destination, observers, abort authority và stop thresholds trước injection. Không làm trên production khi chưa có approval. Success là phát hiện đúng, giữ invariant, phục hồi và thu evidence; không phải pipeline không báo lỗi. Timeline dùng một clock chuẩn và correlation IDs.'),
('Kịch bản throttling','Provider trả 429 theo burst/quota, có và không Retry-After. Client phải classify đúng, obey bounded backoff+jitter, giảm concurrency, giữ deadline/retry budget và không khuếch đại tải. Đo request amplification, in-flight, recovery, source errors và freshness burn. Nested retries bị tắt hoặc accounting chung.'),
('Kịch bản cursor expiry','Opaque cursor hết hạn giữa run; client không chế token. Recovery theo source contract: refresh snapshot/session, resume từ safe typed boundary hoặc restart bounded window rồi dedup/reconcile. Lưu last durable page, filter/order/config và token age. Nếu provider không bảo đảm snapshot, completeness chỉ được kết luận sau key/range reconciliation.'),
('Kịch bản duplicate delivery','Phát cùng record/page/batch hai lần, rồi same identity different payload. Same identity same content phải idempotent; different content là collision/quarantine. Dedup identity phải gồm source/entity/business key/version hoặc batch boundary, không chỉ payload hash. Đo accepted, replayed, rejected và residual duplicates theo target grain.'),
('Quan sát và điều hành','Alert phải dẫn tới runbook action: throttle, pause, refresh auth/cursor, quarantine hoặc replay. Dashboard nối provider status, limiter/retry state, checkpoint, landing ledger, target publish và reconciliation. Operator không chỉnh checkpoint trực tiếp ngoài audited procedure. Communication phân biệt impact thực, risk và unknown.'),
('After-action review','So expected với observed timeline, detection/recovery time, SLO burn và data diff. Ghi control thất bại, contributing conditions, owner/deadline và verification test; không quy lỗi cá nhân. Rerun targeted scenario sau remediation. Chưa có exact input/output hashes và checkpoint states thì exercise chưa chứng minh data correctness.'),
),tuple(f'Game-day probe {i}: injection, expected state, stop rule, observed evidence và reconciliation oracle phải đủ' for i in range(1,16))),
Lesson(247,'Lesson_247-etl-against-elt-where-the-compute-lives','ETL and ELT Where the Compute Lives','135-etl-elt-where-compute-lives.md','wiki.transformation.etl-elt-compute-location','Phân biệt ETL và ELT bằng nơi, thời điểm và trust boundary của compute như thế nào thay vì tranh luận theo khẩu hiệu?',(FD,DD),(FDL,DDL),(
('Định nghĩa bằng execution path','ETL biến đổi trước khi load vào analytical target; ELT load representation sớm rồi biến đổi trong warehouse/lakehouse/engine đích. Cả hai đều có extract, validate, transform và publish; khác placement/order của compute và persistence boundaries. Một pipeline thường hybrid: tokenize trước load, normalize raw-to-staging trong target, aggregate sau đó.'),
('Năm trục quyết định','Data gravity/egress, source and target compute capacity, security/privacy boundary, latency/replay requirements và tooling/governance. Thêm transformation complexity, skill set, observability, portability và unit cost. Không chọn vì cloud warehouse “mạnh” hoặc ETL “cũ”. Mỗi criterion có measurement, constraint và reversal condition.'),
('ETL trade-offs','Pre-load transform giảm dữ liệu nhạy cảm/volume vào target và cho phép specialized compute, nhưng dễ mất raw replay evidence, tăng bespoke runtime và tạo coupled extraction-transform failure. Nếu transform sai trước khi giữ nguồn, repair khó. ETL tốt cần immutable input or re-extract contract, versioned code, rejects/quarantine và reconciliation trước/sau.'),
('ELT trade-offs','Land-first giữ fidelity/replay và tận dụng scalable target SQL, lineage/testing ecosystem; đổi lại raw-zone access/retention, storage/scan cost và target lock-in. “Load raw” vẫn phải qua security, integrity và envelope controls. ELT không cho phép publish partial models hoặc bỏ source impact. Compute location không tự quyết correctness.'),
('Benchmark đúng câu hỏi','Dùng cùng input boundary, transformation semantics và output oracle; đo end-to-end freshness, source load, bytes moved, target compute, cost, failure recovery và operator effort. Whole-stack comparison được ghi đúng phạm vi. Query benchmark bỏ qua extraction, landing và recovery không đủ để quyết định architecture.'),
('Decision case','Với PII-heavy API, database CDC và large files, lập two feasible designs và hybrid. Chọn per stage, ghi rejected options, trust boundary, failure windows, replay path, SLO/cost envelope. ADR chỉ được duyệt khi changed constraint như region, egress price hoặc target capacity làm lựa chọn có thể đảo.'),
),tuple(f'ETL-ELT probe {i}: compute boundary, persisted state, security constraint, recovery path và cost/SLO evidence phải rõ' for i in range(1,16))),
Lesson(248,'Lesson_248-load-semantics-append-upsert-merge-replace-and-swap','Load Semantics Append Upsert Merge Replace and Swap','136-load-semantics-append-upsert-merge-replace-swap.md','wiki.transformation.load-semantics-append-upsert-merge-replace-swap','Chọn load semantics nào để giữ grain, history, delete và atomic visibility của từng dataset?',(DI,PT,FD),(DIL,PTL,FDL),(
('Semantics trước câu lệnh','Append thêm records; upsert insert/update theo key; merge có matched/not-matched clauses và có thể xử lý delete; replace tái tạo whole target; swap publish một prepared version bằng pointer/name/catalog operation. Tên strategy trong tool không đủ: phải ghi key, grain, source boundary, history và visibility.'),
('Append','Đúng cho immutable events hoặc version ledger khi duplicate identity được kiểm. Với mutable entity, append tạo nhiều versions và consumer cần current-view rule. Retry làm duplicate nếu không có event/batch identity. Partition append không đồng nghĩa exactly-once; manifest/checkpoint và dedup vẫn cần.'),
('Upsert và merge','Unique key phải thật sự unique/stable ở source slice và target. Duplicate keys trong incoming batch có thể fail hoặc chọn nondeterministically tùy engine. Define precedence by source version/time with tie breaker. Hard delete cần tombstone/not-matched policy; absent row trong incremental batch không mặc nhiên delete.'),
('Replace và overwrite','Whole replace đơn giản cho small snapshot nếu build off to side, validate rồi atomic publish. Truncate-then-load phơi partial/empty state và crash gap. Partition overwrite cần complete partition boundary và late-data policy; dynamic overwrite nhầm predicate có thể xóa rộng. Retain previous version for rollback.'),
('Swap','Table/view/catalog pointer swap tách build khỏi publish, nhưng atomicity và reader snapshot phụ thuộc engine/catalog. Grants, comments, constraints, indexes, statistics và downstream references phải được preserve/test. Cross-object publication không mặc nhiên atomic. Garbage collection chỉ sau retention and active-reader safety.'),
('Decision matrix lab','Chạy same entity/events dưới append, upsert, merge, replace và swap với update, delete, late arrival, duplicate batch và crash. Kiểm key/grain, current state, history, reader visibility, rerun equality và rollback. Ghi engine/version transaction semantics; không suy từ SQL syntax sang universal guarantee.'),
),tuple(f'Load-semantics probe {i}: grain/key, change operation, publish boundary, reader observation và rerun oracle phải đủ' for i in range(1,16))),
Lesson(249,'Lesson_249-atomic-publish-and-the-partial-state-reader','Atomic Publish and the Partial State Reader','137-atomic-publish-partial-state-reader.md','wiki.transformation.atomic-publish-partial-state-reader','Thiết kế publication thế nào để reader thấy old hoặc new complete state nhưng không thấy trạng thái dở dang?',(PT,IR,DD),(PTL,IRL,DDL),(
('Visibility invariant','Tại logical publication point, mỗi reader được phép thấy complete version V hoặc V+1 theo isolation contract; không thấy mixture vi phạm referential/business invariants. Atomicity scope phải ghi: one table, partition set, manifest snapshot hay multi-table product. Commit success và consumer cache refresh là hai boundaries khác.'),
('Các failure windows','Build partial, validate failure, publish conflict, commit unknown, crash after publish before status/checkpoint và cleanup too early. Mỗi window có durable artifacts, recovery owner và idempotent transition. Publish-first then validate is unsafe; cleanup-old immediately can break long reader. Unknown commit outcome được resolve bằng transaction/snapshot ID, không retry blind.'),
('Patterns','Database transaction covers supported objects; shadow table plus atomic rename/swap where engine guarantees; immutable files plus manifest/catalog pointer; versioned view alias for dataset. Multi-system needs state machine/outbox and reconciliation, not pretend distributed atomicity. Readers must use supported snapshot/pointer, not list staging paths.'),
('Reader tests','Start long reader before publish, short readers during/after, cached BI/session and two-table join. Inject pause between file writes and pointer commit. Assert observed version IDs and invariants; no reader sees unlisted files or mixed keys. Test stale cache explicitly: atomic catalog commit does not invalidate every application cache instantly.'),
('Validation gate','Before publish verify schema/contract, counts/key/hash, constraints, freshness and required cross-table equations. Gate output is bound to exact candidate version hash. Approval and publish use compare-and-set against expected parent to prevent lost update. Failed candidate stays isolated/quarantined with retention policy.'),
('Rollback và cleanup','Rollback republishes previous valid pointer/version, not reconstructs from partial logs. Keep old version until reader lease/time-travel retention and incident window pass. Cleanup records reachability and legal/privacy rules. Measure publish latency, conflict rate, unknown outcomes, rollback time and partial-state detections.'),
),tuple(f'Atomic-publish probe {i}: version identity, commit scope, concurrent reader, injected kill point và invariant oracle phải đủ' for i in range(1,16))),
Lesson(250,'Lesson_250-idempotency-for-batch-deterministic-keys-and-overwrite','Batch Idempotency Deterministic Keys and Overwrite','138-batch-idempotency-deterministic-keys-overwrite.md','wiki.transformation.batch-idempotency-deterministic-keys-overwrite','Một batch rerun cần identity, deterministic computation và publication protocol nào để cho cùng accepted state?',(DI,SI,FD,DD),(DIL,SIL,FDL,DDL),(
('Định nghĩa đúng phạm vi','Idempotency nghĩa là áp cùng logical operation nhiều lần tạo cùng externally observable accepted state trong scope/time window đã nêu. Nó không có nghĩa mọi lần chạy tạo byte-identical files, không phát log hay không tốn compute. Chốt target grain, history policy, side effects và observation boundary trước test.'),
('Deterministic batch identity','Identity ghép source/entity, immutable interval/snapshot, contract/schema version và transformation code/config version; content hash phát hiện collision. Scheduler run ID không phải logical identity vì retry sinh run mới. Same identity same input resumes/dedups; same identity different hash quarantines. Idempotency retention phải phủ retry/backfill horizon.'),
('Deterministic rows','Key từ stable business/source identity và grain; tránh random UUID/current time/unordered row_number. Canonical timezone, decimal, null, sort/tie rules và nondeterministic SQL functions. Dedup có total ordering; nếu two records tie hoàn toàn, contract phải quarantine hoặc define deterministic rule, không chọn tùy physical order.'),
('Overwrite safely','Build complete partition/table version separately, validate, then atomic swap/pointer. `delete where` rồi insert trong separate commits không idempotent dưới crash. Insert overwrite phụ thuộc adapter/partition predicate and transaction semantics. Re-running exact batch replaces same logical scope, không xóa dữ liệu ngoài interval.'),
('Side effects và checkpoint','Audit, notification, downstream trigger và checkpoint cũng cần operation identity/outbox/dedup. Data table đúng nhưng gửi notification hai lần vẫn chưa idempotent end-to-end. Checkpoint advances after durable publish; crash after publish before checkpoint causes replay absorbed by ledger. External sinks có idempotency key hoặc reconciliation/manual state.'),
('Property test','Run same batch twice, kill at each step, reorder inputs, vary worker count và replay overlapping batches. Compare canonical key set/typed hashes/current-history views and side-effect ledger. Inject same ID different content. Pass only when state converges, no out-of-scope deletion and every duplicate/collision explainable. Preserve input/version/fingerprint.'),
),tuple(f'Batch-idempotency probe {i}: logical identity, deterministic key/order, kill point, side-effect ledger và convergence oracle phải đủ' for i in range(1,16))),
)

QUERIES={246:['Game day throttling kiểm gì?','Cursor expiry phục hồi thế nào?','Duplicate delivery phân loại ra sao?'],247:['ETL và ELT khác ở đâu?','Khi nào dùng hybrid ETL ELT?','Benchmark compute placement thế nào?'],248:['Append upsert merge replace swap khác gì?','Khi nào partition overwrite an toàn?','Merge delete semantics là gì?'],249:['Atomic publish invariant là gì?','Partial-state reader kiểm thế nào?','Rollback publication ra sao?'],250:['Batch idempotency định nghĩa thế nào?','Deterministic batch key gồm gì?','Kill-point test cần gì?']}
NEW=((DI,'1_Nguon/Web/SRC-DBT-INCREMENTAL-MODELS.md','https://docs.getdbt.com/docs/build/incremental-models','public-vendor-documentation'),)
def folder(x):return (M16 if x.number==246 else M17)/x.directory
def contract(x):
 t=(folder(x)/'note.md').read_text();z=(folder(x)/'after-note.md').read_text() if (folder(x)/'after-note.md').exists() else ''
 def p(s,k):
  m=re.search(rf'(?m)^\*\*{re.escape(k)}\.\*\*\s*(.+)$',s);return m.group(1).strip() if m else ''
 old=tuple(p(t,k) for k in ('Outcome','Đánh giá','Lab','Pitfalls','Self-study (2,4 giờ)','Done when'))
 if all(old):return old
 q=re.findall(r'(?m)^\*\*Nhiệm vụ\.\*\*\s*(.+)$',z);return p(t,'Năng lực cần chứng minh'),p(z,'Cách đánh giá'),q[0] if q else '',p(z,'Lỗi cần chủ động loại trừ'),q[1] if len(q)>1 else '',p(t,'Điều kiện hoàn thành')
deep=base.deep
def curriculum(x,k):
 o,a,l,p,h,d=contract(x);module='Module 16: Data Ingestion and Integration Engineering' if x.number==246 else 'Module 17: ELT, dbt and Workflow Orchestration';head=f'# Phase 7: Ingestion, Transformation, Quality and Governance\n# {module}\n# Lesson {x.number}: {x.title}';body=re.sub(r'^---\n.*?\n---\n','',k,flags=re.S);body=re.sub(r'^# .+\n+','',body,count=1);note=f'{head}\n\n## Mục tiêu bài học\n\n**Năng lực cần chứng minh.** {o}\n\n**Điều kiện hoàn thành.** {d}\n\n{body}';after=f'{head}\n\n## Thực hành\n\n**Nhiệm vụ.** {l}\n\nChỉ chạy trên fixture/sandbox được phép. Lưu versions, inputs, state trước–sau, kill points, raw outputs, reconciliation và limitations.\n\n## Kiểm tra cuối bài\n\n1. Nêu invariant và phạm vi bảo đảm.\n2. Chỉ ra một failure window.\n3. Phân biệt expected result với evidence đã chạy.\n4. Đưa counterexample làm thiết kế thất bại.\n\n## Tiêu chí hoàn thành\n\n**Cách đánh giá.** {a}\n\n**Điều kiện đạt.** {d}\n\n## Bài làm sau buổi học\n\n**Nhiệm vụ.** {h}\n\n**Lỗi cần chủ động loại trừ.** {p}\n\n## Reference\n\n- Knowledge note: `{(PACK/x.filename).relative_to(ROOT)}`\n- Nội dung học thuật: `note.md` cùng thư mục.\n';return note,after
def manifest(check=False):
 p=ROOT/'Docs/Second-Brain/second-brain-manifest.json';d=json.loads(p.read_text());ids={x[0] for x in NEW};d['source_registry']=[r for r in d['source_registry'] if r.get('source_id') not in ids]+[{'source_id':i,'record_path':q,'canonical_url':u,'captured':'2026-10-02','rights':rights} for i,q,u,rights in NEW];nids={x.note_id for x in LESSONS};d['note_registry']=[n for n in d['note_registry'] if n.get('note_id') not in nids];d['retrieval_test_set']=[q for q in d['retrieval_test_set'] if q.get('expected_note_id') not in nids]
 for x in LESSONS:d['note_registry'].append({'note_id':x.note_id,'path':f'2_Wiki/Database-Systems/{x.title}.md','status':'review','source_ids':list(x.sources),'last_verified':'2026-10-02'});d['retrieval_test_set'].extend({'query':q,'expected_note_id':x.note_id} for q in QUERIES[x.number])
 d.update({'version':'1.0.49','updated_at':'2026-10-02T23:59:20+07:00'});d['layers']['1_Nguon']['source_count']=len(d['source_registry']);d['layers']['2_Wiki']['note_count']=len(d['note_registry']);e=json.dumps(d,ensure_ascii=False,indent=2)+'\n'
 if check:return [] if p.read_text()==e else [str(p.relative_to(ROOT))]
 p.write_text(e);return []
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');a=ap.parse_args();st=[]
 for x in LESSONS:
  k=normalize_markdown(deep(x));n,z=curriculum(x,k)
  for p,c in ((PACK/x.filename,k),(WIKI/f'{x.title}.md',k),(folder(x)/'note.md',n),(folder(x)/'after-note.md',z)):
   if a.check:
    if not p.exists() or p.read_text()!=c:st.append(str(p.relative_to(ROOT)))
   else:p.write_text(c)
 st+=manifest(a.check)
 if st:print('STALE\n'+'\n'.join(st));return 1
 print(('checked' if a.check else 'written')+f'={len(LESSONS)*4} stale=0');return 0
if __name__=='__main__':raise SystemExit(main())
